import{_ as l,a as r,e as t,l as e,ar as n,N as o,t as d}from"./chunks/framework.BahxXRbM.js";const p=JSON.parse('{"title":"前端性能优化面试题","description":"","frontmatter":{"title":"前端性能优化面试题","tags":["interview","performance"]},"headers":[],"relativePath":"interview/Performance.md","filePath":"interview/Performance.md","lastUpdated":1761045430000}'),h={name:"interview/Performance.md"},s={id:"frontmatter-title-答题模板",tabindex:"-1"};function c(i,a,m,u,f,b){return t(),r("div",null,[a[1]||(a[1]=e("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /vite-press/interview/Performance.md for this page in Markdown format",-1)),e("h1",s,[o(d(i.$frontmatter.title)+"答题模板 ",1),a[0]||(a[0]=e("a",{class:"header-anchor",href:"#frontmatter-title-答题模板","aria-label":"Permalink to “{{ $frontmatter.title }}答题模板”"},"​",-1))]),a[2]||(a[2]=n('<h2 id="一、为什么要进行性能优化" tabindex="-1">一、为什么要进行性能优化？ <a class="header-anchor" href="#一、为什么要进行性能优化" aria-label="Permalink to “一、为什么要进行性能优化？”">​</a></h2><ul><li>提升用户体验（加载速度、流畅交互）</li><li>降低跳出率，提高转化率</li><li>对 SEO 有积极影响</li><li>Google 核心指标 Web Vitals 会影响搜索排名</li></ul><hr><h2 id="二、性能优化的维度与常用方案" tabindex="-1">二、性能优化的维度与常用方案 <a class="header-anchor" href="#二、性能优化的维度与常用方案" aria-label="Permalink to “二、性能优化的维度与常用方案”">​</a></h2><h3 id="_1-首屏加载优化" tabindex="-1">1. 首屏加载优化 <a class="header-anchor" href="#_1-首屏加载优化" aria-label="Permalink to “1. 首屏加载优化”">​</a></h3><ul><li>使用 CDN 分发资源</li><li>启用 Gzip/Brotli 压缩</li><li>图片懒加载、压缩与格式优化（WebP）</li><li>Skeleton 屏骨架屏 / loading 占位</li><li>SSR / CSR 混合渲染方案</li><li>合理拆分首屏所需资源</li></ul><h3 id="_2-静态资源优化" tabindex="-1">2. 静态资源优化 <a class="header-anchor" href="#_2-静态资源优化" aria-label="Permalink to “2. 静态资源优化”">​</a></h3><ul><li>Tree Shaking、代码分包（Webpack、Vite）</li><li>使用 HTTP/2 并行加载资源</li><li>字体子集化 + 字体懒加载</li><li>图片/音视频资源采用懒加载 + 解码优化</li></ul><h3 id="_3-渲染与交互优化" tabindex="-1">3. 渲染与交互优化 <a class="header-anchor" href="#_3-渲染与交互优化" aria-label="Permalink to “3. 渲染与交互优化”">​</a></h3><ul><li>合理使用 <code>requestAnimationFrame</code></li><li>避免重排重绘（合并 DOM 操作）</li><li>虚拟列表优化长列表渲染（如 react-window）</li><li>节流、防抖优化事件触发频率</li><li>使用 <code>will-change</code> 提前提示浏览器优化布局</li></ul><h3 id="_4-javascript-执行优化" tabindex="-1">4. JavaScript 执行优化 <a class="header-anchor" href="#_4-javascript-执行优化" aria-label="Permalink to “4. JavaScript 执行优化”">​</a></h3><ul><li>降低主线程阻塞时间（避免 Long Tasks）</li><li>使用 Web Worker 分担计算任务</li><li>按需加载组件（import() 动态引入）</li><li>组件懒加载 + 路由懒加载</li></ul><h3 id="_5-缓存与离线优化" tabindex="-1">5. 缓存与离线优化 <a class="header-anchor" href="#_5-缓存与离线优化" aria-label="Permalink to “5. 缓存与离线优化”">​</a></h3><ul><li>利用浏览器缓存、Service Worker 缓存关键资源</li><li>设置合理的 Cache-Control / ETag</li><li>IndexedDB 本地缓存用户数据</li></ul><h3 id="_6-数据请求优化" tabindex="-1">6. 数据请求优化 <a class="header-anchor" href="#_6-数据请求优化" aria-label="Permalink to “6. 数据请求优化”">​</a></h3><ul><li>请求合并、分页、懒加载</li><li>使用 SWR、React Query 做缓存与请求状态控制</li><li>减少重复请求，接口防抖</li></ul><h3 id="_7-性能监控与持续评估" tabindex="-1">7. 性能监控与持续评估 <a class="header-anchor" href="#_7-性能监控与持续评估" aria-label="Permalink to “7. 性能监控与持续评估”">​</a></h3><ul><li>接入 Sentry、LogRocket、Lighthouse CI、Web Vitals SDK</li><li>监控用户真实使用情况（RUM）</li><li>定期分析 Bundle Size、加载时长、JS 执行瓶颈</li></ul><hr><h2 id="三、常见优化误区" tabindex="-1">三、常见优化误区 <a class="header-anchor" href="#三、常见优化误区" aria-label="Permalink to “三、常见优化误区”">​</a></h2><ul><li>一味压缩代码，忽略模块分割</li><li>使用 SSR 但没有缓存策略，反而变慢</li><li>滥用 useEffect / 监听导致频繁更新</li><li>不合理的动画/transition 影响帧率</li></ul><hr><h2 id="四、总结语-面试收尾" tabindex="-1">四、总结语（面试收尾） <a class="header-anchor" href="#四、总结语-面试收尾" aria-label="Permalink to “四、总结语（面试收尾）”">​</a></h2><blockquote><p>性能优化没有银弹，通常是围绕用户体验、加载速度和交互流畅性进行综合提升。我的策略是先监控、识别瓶颈，然后有针对性地优化关键路径，同时保证优化手段具备可维护性与成本效益。</p></blockquote>',24))])}const k=l(h,[["render",c]]);export{p as __pageData,k as default};
